class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            by_right[b].append((a, i))
        top1 = (0, -1)
        top2 = (0, -1)
        gains = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for item in by_right[r]:
                if item[0] > top1[0]:
                    top2, top1 = top1, item
                elif item[0] > top2[0]:
                    top2 = item
            total += r - top1[0]
            if top1[1] >= 0:
                gains[top1[1]] += top1[0] - top2[0]
        return total + max(gains)

