import sys
from functools import lru_cache

# Count standard tableaux of the near-rectangular shape for small instances.
# A tableau is represented by the order in which its cells are filled.
def solve(A, B, M):
    lengths = [A] * (B - 1) + [A - 1]
    cells = [(r, c) for r in range(B) for c in range(lengths[r])]
    n = len(cells)
    idx = {p: i for i, p in enumerate(cells)}
    pred = [0] * n
    for i, (r, c) in enumerate(cells):
        if r and c < lengths[r - 1]:
            pred[i] |= 1 << idx[(r - 1, c)]
        if c:
            pred[i] |= 1 << idx[(r, c - 1)]
    full = (1 << n) - 1
    target1, target2 = idx[(0, A - 2)], idx[(0, A - 1)]

    @lru_cache(None)
    def dp(mask, prior1, prior2):
        if mask == full:
            return int(prior2 - prior1 > 1)
        ans = 0
        for i in range(n):
            bit = 1 << i
            if not mask & bit and pred[i] & mask == pred[i]:
                # Number of cells placed so far is the value assigned next.
                value = mask.bit_count() + 1
                p1, p2 = prior1, prior2
                if i == target1: p1 = value
                if i == target2: p2 = value
                ans += dp(mask | bit, p1, p2)
        return ans

    good = dp(0, 0, 0)
    # Recording tableaux can be any standard tableau of this shape.
    @lru_cache(None)
    def count(mask):
        if mask == full: return 1
        s = 0
        for i in range(n):
            bit = 1 << i
            if not mask & bit and pred[i] & mask == pred[i]:
                s += count(mask | bit)
        return s
    return good * count(0) % M

