class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        # Pascal row for binomial coefficients up to m
        C = [[0] * (m + 1) for _ in range(m + 1)]
        C[0][0] = 1
        for a in range(1, m + 1):
            C[a][0] = C[a][a] = 1
            for b in range(1, a):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD
        counts = [0] * (m + 1)
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = m - i - 1
                for j in range(used, m + 1):
                    need = j - used
                    if 0 <= need <= rem:
                        counts[j] = (counts[j] + C[rem][need]) % MOD
                used += 1
        ans = 0
        for j in range(1, m + 1):
            # Number of popcount steps needed to reduce j to 1
            v = j
            steps = 0
            while v != 1:
                v = v.bit_count()
                steps += 1
            if steps <= k - 1:
                ans = (ans + counts[j]) % MOD
        return ans

