import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    H,W,X=data[:3]
    P,Q=data[3]-1,data[4]-1
    vals=data[5:]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    power=vals[start]
    pq=[]
    def add(r,c):
        idx=r*W+c
        if not seen[idx]:
            seen[idx]=1
            heapq.heappush(pq,(vals[idx],idx))
    for r,c in ((P-1,Q),(P+1,Q),(P,Q-1),(P,Q+1)):
        if 0<=r<H and 0<=c<W: add(r,c)
    while pq and pq[0][0]*X < power:
        v,idx=heapq.heappop(pq)
        power+=v
        r,c=divmod(idx,W)
        if r: add(r-1,c)
        if r+1<H: add(r+1,c)
        if c: add(r,c-1)
        if c+1<W: add(r,c+1)
    print(power)
